'use strict';
// Independent acceptance checks; production changes must be generated by Buildroom.
const assert = require('node:assert/strict');
const fs = require('node:fs');
const path = require('node:path');
const html = fs.readFileSync(path.join(__dirname, '..', 'index.html'), 'utf8');
const markup = html.replace(/<script\b[^>]*>[\s\S]*?<\/script>/gi, '');
const ids = Array.from(markup.matchAll(/\bid\s*=\s*["']([^"']+)["']/g), match => match[1]);
assert.equal(new Set(ids).size, ids.length, 'Live HTML IDs must remain unique');
const help = markup.match(/<div class="control-help">([\s\S]*?)<\/div>/)?.[1];
assert.ok(help, 'Keep the pause control-help region');
const keyboard = help.match(/<b>KEYBOARD<\/b>([\s\S]*?)<\/p>/)?.[1]?.replace(/<[^>]*>/g, ' ');
assert.ok(keyboard, 'Keep a labeled keyboard section');
assert.match(keyboard, /(?:accelerat|throttle)/i, 'Explain acceleration explicitly');
assert.match(keyboard, /brak/i, 'Explain braking explicitly');
assert.match(keyboard, /steer/i, 'Explain steering explicitly');
assert.match(keyboard, /Space\s*(?:[—:–-]\s*)?(?:handbrake|drift)/i, 'Space is drift, not boost');
assert.match(keyboard, /Shift\s*(?:[—:–-]\s*)?boost/i, 'Shift is boost, not drift');
assert.match(keyboard, /(?:Esc(?:ape)?[^.]*resume|resume[^.]*Esc(?:ape)?)/i, 'Explain pause and resume');
assert.match(help, /TOUCH/i, 'Keep touch controls');
assert.match(help, /CONTROLLER/i, 'Keep controller controls');
for (const [key, action] of [['T', 'transform'], ['E', 'pulse'], ['C', 'camera'], ['R', 'recover']]) {
  assert.match(keyboard, new RegExp('\\b' + key + '\\s*(?:[—:–-]\\s*)?(?:changes?\\s+|switch(?:es)?\\s+|toggles?\\s+)?' + action, 'i'), 'Preserve ' + key + ' ' + action + ' guidance');
}
for (const mode of ['free', 'run', 'pursuit', 'arena']) assert.ok(html.includes(`data-mode="${mode}"`));
assert.ok(html.includes('995.reborn.save.v1'), 'Preserve saved progress identity');
console.log('Control instructions, unique IDs, modes and save identity verified');
